export type WayOutRow = {
	/**
	 *  It can be used now, as far as the Advisor can tell: drawn ✓, else ✕. `None` for Ways Out
	 *  a Gap hides, such as the spells of a spell list never read, drawn `?`.
	 */
	usable: boolean | null,
	/**  What it is, such as `Stone staircase leading down` or `Teleportation`. */
	name: string,
	/**
	 *  A short fact beside the name, such as `7 steps` or `spell · 4% fail`, marked when the
	 *  menu or list it was read off is out of date.
	 */
	detail: MarkedValue | null,
	/**
	 *  Why it can't be used, when it can't, such as `Centaur is faster`, marked when it rests on
	 *  a menu out of date.
	 */
	whyNot: MarkedValue | null,
};

/**  The Ways Out as the panel lists them: a ✓ or ✕ for each, with why not. */
export type WaysOutList = {
	/**
	 *  One staircase each way, the nearest that can be used or else the nearest, then each
	 *  escape carried, ability and spell.
	 */
	rows: WayOutRow[],
	/**
	 *  The ground the player stands on, such as `In a corridor: 2 sides open`, once the Advisor
	 *  can tell.
	 */
	ground: string | null,
	/**
	 *  What keeps the Advisor from judging more, such as the map not yet sent, one sentence
	 *  each: the Ways Out a Gap hides are rows of their own.
	 */
	gaps: string[],
};

/**  How the app's window behaves, in Settings → Connection and window. */
export type WindowView = {
	/**  The app starts in the tray at login. */
	startAtLogin: boolean,
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

